import{_ as i,c as l,o,a5 as a}from"./chunks/framework.DuCYAsAJ.js";const u=JSON.parse('{"title":"崩溃一致性、日志、LFS 与数据完整性","description":"","frontmatter":{"title":"崩溃一致性、日志、LFS 与数据完整性","date":"2026-04-03T00:00:00.000Z","order":7},"headers":[],"relativePath":"posts/os/ostep/log.md","filePath":"posts/os/ostep/log.md","lastUpdated":1775711869000}'),s={name:"posts/os/ostep/log.md"};function n(d,e,t,c,r,p){return o(),l("div",null,[...e[0]||(e[0]=[a('<h3 id="崩溃一致性与日志" tabindex="-1">崩溃一致性与日志 <a class="header-anchor" href="#崩溃一致性与日志" aria-label="Permalink to &quot;崩溃一致性与日志&quot;">​</a></h3><p>前面几章里，文件系统已经有了 inode、目录、位图、数据块这些核心结构。问题在于，这些结构不是内存里的临时数据，而是要持久放在磁盘上的。一旦系统在更新过程中断电或崩溃，磁盘上就可能只留下“更新到一半”的状态，这就是崩溃一致性 <code>crash consistency</code>问题</p><p>和普通内存数据结构不同，磁盘更新不能假设“一组修改会同时完成”。文件系统往往必须把几个块分开写出，而系统可能恰好在任意两次写入之间崩溃。那么文件系统该如何把磁盘状态从一个一致状态安全地推进到下一个一致状态？</p><h4 id="一个追加写的例子" tabindex="-1">一个追加写的例子 <a class="header-anchor" href="#一个追加写的例子" aria-label="Permalink to &quot;一个追加写的例子&quot;">​</a></h4><p>假设现在有一个很简单的文件系统，里面有：</p><ul><li>inode 位图</li><li>数据位图</li><li>inode 表</li><li>数据块区域</li></ul><p>某个文件当前只占用一个数据块，inode 大致如下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I[v1]</span></span>\n<span class="line"><span>owner: remzi</span></span>\n<span class="line"><span>permissions: read-write</span></span>\n<span class="line"><span>size: 1</span></span>\n<span class="line"><span>pointer[0]: 4</span></span>\n<span class="line"><span>pointer[1]: null</span></span>\n<span class="line"><span>pointer[2]: null</span></span>\n<span class="line"><span>pointer[3]: null</span></span></code></pre></div><p>现在用户做了一次典型的追加写：把一个新的 4KB 数据块追加到文件尾部。文件系统至少要更新 3 处磁盘状态：</p><ul><li>新数据块 <code>Db</code></li><li>数据位图 <code>B[v2]</code>，把新块标记为已分配</li><li>inode <code>I[v2]</code>，把文件大小改为 2，并让第二个指针指向新块 5</li></ul><p>更新后的 inode 变成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I[v2]</span></span>\n<span class="line"><span>owner: remzi</span></span>\n<span class="line"><span>permissions: read-write</span></span>\n<span class="line"><span>size: 2</span></span>\n<span class="line"><span>pointer[0]: 4</span></span>\n<span class="line"><span>pointer[1]: 5</span></span>\n<span class="line"><span>pointer[2]: null</span></span>\n<span class="line"><span>pointer[3]: null</span></span></code></pre></div><p>理想情况当然是这 3 个块一起“原子切换”到新状态。但真实磁盘不会替你完成这种高层原子性；它只会接收一个个独立的写请求</p><h4 id="为什么会出错" tabindex="-1">为什么会出错 <a class="header-anchor" href="#为什么会出错" aria-label="Permalink to &quot;为什么会出错&quot;">​</a></h4><p>如果 3 次写入里只完成了其中一部分，问题就出现了：</p><ul><li>只写入 <code>Db</code>：磁盘上多了一块没人引用的数据，从元数据看这次写入像没发生过</li><li>只写入 <code>I[v2]</code>：inode 指向了还没真正写好的块，读文件时可能读到垃圾；同时 inode 和位图也不一致</li><li>只写入 <code>B[v2]</code>：位图说块 5 已占用，但没有任何 inode 指向它，造成<strong>空间泄漏</strong></li><li>写入 <code>I[v2]</code> 和 <code>B[v2]</code>，但没写 <code>Db</code>：元数据彼此一致，但文件内容是垃圾</li><li>写入 <code>I[v2]</code> 和 <code>Db</code>，但没写 <code>B[v2]</code>：文件内容在，位图却没记录，仍然不一致</li><li>写入 <code>B[v2]</code> 和 <code>Db</code>，但没写 <code>I[v2]</code>：块被占用，但没人知道它属于哪个文件</li></ul><h3 id="方案-1-fsck" tabindex="-1">方案 1：<code>fsck</code> <a class="header-anchor" href="#方案-1-fsck" aria-label="Permalink to &quot;方案 1：`fsck`&quot;">​</a></h3><p>早期文件系统的思路很直接：先允许不一致发生，等系统重启时再统一修</p><p><code>fsck</code> 就是这种思路的代表。它在文件系统挂载前扫描整个磁盘，尽量把元数据修回一个自洽状态。常见工作包括：</p><ul><li>检查超级块是否合理</li><li>扫描 inode、间接块等信息，重建正确的空闲块位图</li><li>检查 inode 的类型和字段是否损坏</li><li>重新计算每个 inode 的链接计数</li><li>处理重复块引用</li><li>清理越界或明显错误的块指针</li><li>检查目录项格式、<code>.</code> 和 <code>..</code>、层次结构是否合理</li><li>把没有目录引用的 inode 挪到 <code>lost+found</code></li></ul><p><code>fsck</code> 能解决的是<strong>元数据内部一致性</strong>，但它并不能保证用户数据一定正确。例如前面那种“inode 和位图都对，但数据块里是垃圾”的情况，<code>fsck</code> 往往无能为力</p><p>它最大的问题是慢。明明可能只是在 3 个块的更新过程中崩溃了，恢复时却要扫描整个磁盘。磁盘越大，这种做法越难接受</p><h3 id="方案-2-日志-journaling" tabindex="-1">方案 2：日志 <code>journaling</code> <a class="header-anchor" href="#方案-2-日志-journaling" aria-label="Permalink to &quot;方案 2：日志 `journaling`&quot;">​</a></h3><p>比 <code>fsck</code> 更积极的办法，是在真正覆写文件系统之前，先把“我要做什么”写到一个专门区域里。这个想法来自数据库，叫<strong>预写日志 <code>write-ahead logging</code></strong>；在文件系统里通常直接叫<strong>日志 <code>journaling</code></strong></p><p>核心思路很简单：</p><ol><li>先把即将发生的更新写入日志</li><li>确认日志落盘</li><li>再把这些更新写到它们的最终位置</li></ol><p>这样，如果系统在中途崩溃，恢复程序只需要查看日志并重放已提交事务，而不用扫描整个磁盘</p><h4 id="数据日志-data-journaling" tabindex="-1">数据日志 <code>data journaling</code> <a class="header-anchor" href="#数据日志-data-journaling" aria-label="Permalink to &quot;数据日志 `data journaling`&quot;">​</a></h4><p>最直接的版本是把<strong>元数据和用户数据都写进日志</strong>。对前面的追加写例子，一次事务大致包含：</p><ul><li><code>TxB</code>：事务开始块，说明这是哪个事务、将更新哪些最终位置</li><li>日志中的块内容：<code>I[v2]</code>、<code>B[v2]</code>、<code>Db</code></li><li><code>TxE</code>：事务提交块，表示事务完整落盘</li></ul><p>这种把完整块内容直接写进日志的方式，可以理解为<strong>物理日志 <code>physical logging</code></strong></p><p>可以把协议理解为 4 步：</p><ol><li><strong>日志写入</strong>：把 <code>TxB</code> 和所有待更新内容写入日志</li><li><strong>日志提交</strong>：最后写 <code>TxE</code>，事务才算真正提交</li><li><strong>加检查点 <code>checkpoint</code></strong>：把这些块拷贝到文件系统中的最终位置</li><li><strong>释放日志空间</strong>：等检查点完成后，标记这段日志可以复用</li></ol><p>恢复时的规则也很直接：</p><ul><li>如果崩溃发生在 <code>TxE</code> 写入前，说明事务没提交，直接丢弃</li><li>如果 <code>TxE</code> 已写入，但检查点没做完，就从日志重放这笔事务</li></ul><p>这是一种典型的<strong>重做日志 <code>redo logging</code></strong></p><h4 id="为什么提交块必须最后写" tabindex="-1">为什么提交块必须最后写 <a class="header-anchor" href="#为什么提交块必须最后写" aria-label="Permalink to &quot;为什么提交块必须最后写&quot;">​</a></h4><p>这里的问题是磁盘和 I/O 子系统会<strong>重排序写入</strong>。即便操作系统“一次发了 5 个块”，磁盘内部也可能先把 <code>TxE</code> 写上去，再慢慢写别的块。如果 <code>TxE</code> 先落盘，而事务内容里某个数据块还没真正写进日志，恢复程序会误以为“这是一个完整事务”，然后把不完整的数据重放到正式位置，结果反而把垃圾写进文件系统。所以日志协议必须强制一个顺序：</p><ul><li>事务内容必须先稳定写到日志</li><li>之后才能写提交块 <code>TxE</code></li></ul><p>现代系统通常要借助刷盘、屏障 <code>barrier</code>、缓存同步等机制来实现这个顺序保证。提交块本身通常也会做成一个足够小、能够原子落盘的写入，这样恢复时只需要判断它是否真正存在即可</p><h4 id="批处理和循环日志" tabindex="-1">批处理和循环日志 <a class="header-anchor" href="#批处理和循环日志" aria-label="Permalink to &quot;批处理和循环日志&quot;">​</a></h4><p>如果每次系统调用都单独生成一笔日志事务，写放大会很严重。实际文件系统通常会把一段时间内的多次修改缓冲在内存里，合并成一个较大的全局事务再提交，这样可以减少重复写</p><p>日志空间本身也是有限的，因此它通常被实现成<strong>循环日志 <code>circular log</code></strong>。文件系统会在日志超级块中记录：</p><ul><li>最旧的未检查点事务</li><li>最新写入的位置</li></ul><p>一旦某个事务已经成功加检查点，就可以把那段日志标记为空闲，下次继续复用</p><h4 id="元数据日志-metadata-journaling" tabindex="-1">元数据日志 <code>metadata journaling</code> <a class="header-anchor" href="#元数据日志-metadata-journaling" aria-label="Permalink to &quot;元数据日志 `metadata journaling`&quot;">​</a></h4><p>完整数据日志的缺点也很明显：<strong>数据被写了两遍</strong></p><ul><li>第一次写进日志</li><li>第二次写到正式位置</li></ul><p>而磁盘的大头流量往往正是用户数据。于是更常见的折中方案出现了：<strong>只记录元数据，不记录普通文件数据</strong>。Linux ext3 的 ordered 模式就是典型例子。这时协议变成：</p><ol><li>先把数据块 <code>Db</code> 写到它的最终位置</li><li>再把元数据 <code>I[v2]</code>、<code>B[v2]</code> 写入日志</li><li>写入提交块 <code>TxE</code></li><li>把元数据加检查点到正式位置</li><li>释放日志空间</li></ol><p><strong>先写被指向的对象，再写指针本身</strong>，也就是说，必须先让数据块安全落盘，再让 inode 指向它。这样即使崩溃，inode 也不会指向垃圾数据</p><p>这就是为什么**有序元数据日志 <code>ordered journaling</code>**在现实里很常见：它保住了大部分性能，又避免了“元数据正确但指向垃圾”的严重问题。一些文件系统还提供 unordered 模式，依然保证元数据一致，但数据语义会更弱</p><h4 id="块复用为什么麻烦" tabindex="-1">块复用为什么麻烦 <a class="header-anchor" href="#块复用为什么麻烦" aria-label="Permalink to &quot;块复用为什么麻烦&quot;">​</a></h4><p>日志还有一个容易踩坑的边角问题：<strong>块复用</strong></p><p>比如某个目录块 <code>1000</code> 之前被记录进日志；后来这个目录被删除，块 <code>1000</code> 被释放；再后来，一个新文件正好复用了块 <code>1000</code> 作为自己的数据块。此时如果系统崩溃，恢复程序天真地重放老日志，就可能把“旧目录内容”重新写回块 <code>1000</code>，从而覆盖新文件的数据</p><p>ext3 为此引入了 <strong>revoke record</strong>。它的作用可以理解为一句话：<strong>这个块过去虽然出现在旧事务里，但现在已经无效，恢复时不要再重放它</strong></p><h3 id="其他方法" tabindex="-1">其他方法 <a class="header-anchor" href="#其他方法" aria-label="Permalink to &quot;其他方法&quot;">​</a></h3><p>除了 <code>fsck</code> 和 journaling，文件系统还尝试过其他崩溃一致性方案</p><h4 id="软更新-soft-updates" tabindex="-1">软更新 <code>soft updates</code> <a class="header-anchor" href="#软更新-soft-updates" aria-label="Permalink to &quot;软更新 `soft updates`&quot;">​</a></h4><p>软更新不依赖单独的日志区域，而是通过极其仔细的写入排序规则，让磁盘上的结构始终不落入明显不一致的状态。它的优势是不用额外写整份日志；代价是实现复杂度很高，因为系统必须理解并维护各种元数据之间的依赖关系</p><h4 id="写时复制-copy-on-write" tabindex="-1">写时复制 <code>Copy-On-Write</code> <a class="header-anchor" href="#写时复制-copy-on-write" aria-label="Permalink to &quot;写时复制 `Copy-On-Write`&quot;">​</a></h4><p>COW 的思路是：<strong>永远不在原地覆写旧结构</strong>。有更新时，直接把新版本写到磁盘的空闲位置，等整套新结构都准备好后，再原子地切换根指针。ZFS 等文件系统大量使用这一思路。它天然适合和快照等特性结合</p><h4 id="其他研究方向" tabindex="-1">其他研究方向 <a class="header-anchor" href="#其他研究方向" aria-label="Permalink to &quot;其他研究方向&quot;">​</a></h4><p>书里还提到了一些更偏研究的方案：</p><ul><li><strong>基于反向指针的一致性 <code>BBC</code></strong>：给块增加反向指针，用于判断正向引用是否真的安全落盘</li><li><strong>乐观崩溃一致性 <code>OCC</code></strong>：尽量少等待磁盘，通过校验和等手段在恢复时发现不一致并修正</li></ul><p>它们的共同目标都一样：尽量少牺牲正常写入性能，同时在崩溃后还能快速、安全地恢复</p><h3 id="日志结构文件系统-lfs" tabindex="-1">日志结构文件系统 <code>LFS</code> <a class="header-anchor" href="#日志结构文件系统-lfs" aria-label="Permalink to &quot;日志结构文件系统 `LFS`&quot;">​</a></h3><p>上一部分讨论的是：在原地更新文件系统时，如何靠 <code>fsck</code> 或 journaling 保住一致性。LFS 走的是另一条路：<strong>既然随机写很贵，那就尽量不要原地覆写，而是把所有更新都整理成顺序写</strong>。这套思路由 Berkeley 的 Rosenblum 和 Ousterhout 在 90 年代初系统化提出，名字就叫<strong>日志结构文件系统 <code>Log-structured File System</code></strong></p><h4 id="为什么会有-lfs" tabindex="-1">为什么会有 LFS <a class="header-anchor" href="#为什么会有-lfs" aria-label="Permalink to &quot;为什么会有 LFS&quot;">​</a></h4><p>LFS 的出发点来自几个很实际的观察：</p><ul><li>内存越来越大，更多读请求会被缓存命中，磁盘 I/O 越来越偏向写入</li><li>磁盘的顺序带宽增长很快，但寻道和旋转延迟改善很慢，随机 I/O 和顺序 I/O 的差距越来越大</li><li>传统文件系统在小文件创建、目录更新这类常见负载上会触发一串分散写入，吞吐并不理想</li><li>在 RAID-4/5 上，小写入还有额外放大问题，传统布局经常踩中最差路径</li></ul><p>所以 LFS 想解决的核心问题是能不能把文件系统里的几乎所有写入，都变成大块的顺序写？</p><h4 id="核心思路-永远往空闲位置追加" tabindex="-1">核心思路：永远往空闲位置追加 <a class="header-anchor" href="#核心思路-永远往空闲位置追加" aria-label="Permalink to &quot;核心思路：永远往空闲位置追加&quot;">​</a></h4><p>LFS 的核心非常直接：</p><ul><li>把数据块、inode、目录块、imap 等更新先缓冲在内存里</li><li>缓冲到足够多时，组成一个大块连续写入</li><li>始终写到磁盘的空闲区域</li><li>从不原地覆写旧版本</li></ul><p>也就是说，LFS 不是“找到旧块然后改掉”，而是“把新版本整个追加到磁盘后面”。因此它天然带有很强的 <strong>append-only</strong> 和 <strong>copy-on-write</strong> 色彩</p><h4 id="只顺序还不够-还要足够大" tabindex="-1">只顺序还不够，还要足够大 <a class="header-anchor" href="#只顺序还不够-还要足够大" aria-label="Permalink to &quot;只顺序还不够，还要足够大&quot;">​</a></h4><p>LFS 很强调“段 <code>segment</code>”这个概念。<strong>只按逻辑顺序写，并不自动等于高性能</strong></p><p>如果你在时刻 <code>T</code> 写一个块到地址 <code>A</code>，过一小会儿再写地址 <code>A+1</code>，磁盘也可能已经转过去了；第二次写依然要等一整圈旋转，性能还是差。所以真正高效的办法不是“零散地顺序写”，而是：</p><ul><li>一次发出一大批连续写入</li><li>让定位成本被足够多的数据摊薄</li></ul><p>LFS 用的就是经典的<strong>写缓冲 <code>write buffering</code></strong>。它先在内存里积累修改，等够大了再一次性写出。这个“一次性写出的单位”就是段</p><h4 id="段要多大才合适" tabindex="-1">段要多大才合适 <a class="header-anchor" href="#段要多大才合适" aria-label="Permalink to &quot;段要多大才合适&quot;">​</a></h4><p>书里给了一个很实用的估算：如果磁盘定位时间是 <code>T_position</code>，峰值带宽是 <code>R_peak</code>，希望最终有效带宽达到峰值的 <code>F</code>，那么大概要缓冲：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>D = F / (1 - F) * R_peak * T_position</span></span></code></pre></div><p>其中 <code>D</code> 是每次最好写出的数据量</p><p>举个例子：</p><ul><li><code>T_position = 10ms</code></li><li><code>R_peak = 100MB/s</code></li><li>希望达到 <code>90%</code> 峰值带宽</li></ul><p>那么大概需要：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>D = 0.9 / 0.1 * 100MB/s * 0.01s = 9MB</span></span></code></pre></div><p>这说明 LFS 想跑得好，段通常不能太小。写得越大，就越接近磁盘的顺序带宽上限</p><h4 id="新问题-inode-到处移动-怎么找" tabindex="-1">新问题：inode 到处移动，怎么找 <a class="header-anchor" href="#新问题-inode-到处移动-怎么找" aria-label="Permalink to &quot;新问题：inode 到处移动，怎么找&quot;">​</a></h4><p>传统 UNIX 文件系统里，inode 通常放在固定区域里，给定 inode 号后，很容易算出它在磁盘上的位置</p><p>但 LFS 恰恰相反：</p><ul><li>inode 会随着每次更新被写到新位置</li><li>旧版本不会被覆盖</li><li>最新 inode 可能散落在磁盘任意地方</li></ul><p>这就引出了 LFS 最关键的数据结构之一：<strong>inode map <code>imap</code></strong></p><h4 id="imap-给-inode-再加一层间接" tabindex="-1"><code>imap</code>：给 inode 再加一层间接 <a class="header-anchor" href="#imap-给-inode-再加一层间接" aria-label="Permalink to &quot;`imap`：给 inode 再加一层间接&quot;">​</a></h4><p><code>imap</code> 本质上就是一个映射表：</p><ul><li>输入：inode 号</li><li>输出：这个 inode 最新版本所在的磁盘地址</li></ul><p>于是，inode 可以自由迁移，目录里保存的 inode 号却不用跟着改。每次 inode 被写到新位置，只需要同步更新 <code>imap</code> 即可。这是一个非常典型的“加中间层解决问题”的例子。它的代价是多了一层查找；它的好处是让文件系统可以自由移动 inode，而不用沿着整个目录树级联修改</p><h4 id="检查点区域-cr" tabindex="-1">检查点区域 <code>CR</code> <a class="header-anchor" href="#检查点区域-cr" aria-label="Permalink to &quot;检查点区域 `CR`&quot;">​</a></h4><p>但 <code>imap</code> 本身也在不断变化，也会被写到新位置。那系统启动时怎么知道“最新的 imap 在哪里”？</p><p>LFS 的做法是再保留一个固定位置的数据结构：<strong>检查点区域 <code>checkpoint region, CR</code></strong>。CR 存在磁盘上的固定位置，里面记录：</p><ul><li>最新 <code>imap</code> 片段的位置</li><li>日志头尾等必要恢复信息</li></ul><p>于是查找链条变成先读固定位置的 <code>CR</code>-&gt;找到最新 <code>imap</code>-&gt;找到目标 inode-&gt;找到数据块。这也是 LFS 启动和挂载时的起点</p><h4 id="读取文件时实际发生什么" tabindex="-1">读取文件时实际发生什么 <a class="header-anchor" href="#读取文件时实际发生什么" aria-label="Permalink to &quot;读取文件时实际发生什么&quot;">​</a></h4><p>如果内存里什么都没有，从磁盘读取一个文件大致会经历这几步：</p><ol><li>读取 <code>CR</code>，根据 <code>CR</code> 找到并加载 <code>imap</code></li><li>用 inode 号在 <code>imap</code> 中找到 inode 地址</li><li>读取 inode，再根据 inode 的直接或间接指针读取数据块</li></ol><p>也就是说，LFS 在读路径上并没有魔法。它只是比传统文件系统多了 <code>CR -&gt; imap</code> 这一层定位。但如果 <code>imap</code> 常驻内存，这个额外成本在正常情况下并不大</p><h4 id="目录怎么处理" tabindex="-1">目录怎么处理 <a class="header-anchor" href="#目录怎么处理" aria-label="Permalink to &quot;目录怎么处理&quot;">​</a></h4><p>LFS 并没有发明一套全新的目录格式。目录仍然是：</p><ul><li>文件名</li><li>inode 号</li></ul><p>的映射集合。</p><p>比如新建文件 <code>foo</code> 时，LFS 会顺序写出：</p><ul><li>新文件的数据块</li><li>新文件的 inode</li><li>父目录更新后的数据块</li><li>父目录的新 inode</li><li>对应更新过的 <code>imap</code> 片段</li></ul><p>这时 <code>imap</code> 的价值就更明显了。因为目录里存的是 inode 号，而不是 inode 的物理地址，所以 inode 移动并不会逼着父目录、祖先目录一路改上去。LFS 用 <code>imap</code> 避开了经典的<strong>递归更新问题 <code>recursive update problem</code></strong></p><h4 id="代价-旧版本会变成垃圾" tabindex="-1">代价：旧版本会变成垃圾 <a class="header-anchor" href="#代价-旧版本会变成垃圾" aria-label="Permalink to &quot;代价：旧版本会变成垃圾&quot;">​</a></h4><p>LFS 通过“永不原地覆盖”换来了顺序写性能，但也引入了新的问题：<strong>垃圾回收</strong></p><p>因为每次修改文件，新的数据块和 inode 都会被写到新位置，旧版本会留在磁盘上。它们可能是：</p><ul><li>仍然有效的旧块</li><li>已经失效、再也不会被访问的垃圾块</li></ul><p>如果一直不清理，磁盘迟早会被这些旧版本填满</p><h4 id="清理器-cleaner" tabindex="-1">清理器 <code>cleaner</code> <a class="header-anchor" href="#清理器-cleaner" aria-label="Permalink to &quot;清理器 `cleaner`&quot;">​</a></h4><p>LFS 的后台会运行一个清理器：</p><ul><li>读入若干旧段</li><li>判断其中哪些块还活着</li><li>把活块重新整理到更少的新段里</li><li>释放原来的整段空间</li></ul><p>这里按<strong>段</strong>清理非常关键。因为如果只零散回收单个块，磁盘上会形成很多碎洞，后续就很难再找到足够大的连续空闲空间，LFS 赖以生存的顺序写性能也会迅速塌掉</p><p>所以 cleaner 的本质不是简单“删垃圾”，而是：</p><ul><li><strong>压实活数据</strong></li><li><strong>回收整段连续空间</strong></li></ul><h4 id="怎么判断一个块还活着" tabindex="-1">怎么判断一个块还活着 <a class="header-anchor" href="#怎么判断一个块还活着" aria-label="Permalink to &quot;怎么判断一个块还活着&quot;">​</a></h4><p>给定某个旧段里的数据块，LFS 需要知道它现在是不是文件系统里的最新版本。为此，LFS 会在每个段前面保存<strong>段摘要块 <code>segment summary block</code></strong>，记录每个块对应的：</p><ul><li>inode 号</li><li>文件内偏移</li></ul><p>判断流程可以概括成：</p><ol><li>从段摘要里读出这个块属于哪个 inode、对应哪个逻辑偏移</li><li>通过 <code>imap</code> 找到该 inode 的最新地址</li><li>读取 inode，查看它在这个偏移上当前指向哪个磁盘地址</li><li>如果还指向这个块，说明它是活的；否则它已经被新版本替代，是垃圾</li></ol><p>伪代码就是：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(N, T) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> SegmentSummary</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[A];</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">inode </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Read</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">imap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[N]);</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">inode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[T] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> A)</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // live</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // garbage</span></span></code></pre></div><p>LFS 还会配合版本号等技巧，尽量减少为判断死活而产生的额外 I/O</p><h4 id="策略问题-什么时候清-清哪些" tabindex="-1">策略问题：什么时候清，清哪些 <a class="header-anchor" href="#策略问题-什么时候清-清哪些" aria-label="Permalink to &quot;策略问题：什么时候清，清哪些&quot;">​</a></h4><p>机制只是第一步，真正难的是策略：</p><ul><li>什么时候启动 cleaner</li><li>优先清理哪些段</li></ul><p>最直观的时机包括：</p><ul><li>周期性触发</li><li>系统空闲时触发</li><li>磁盘接近写满时触发</li></ul><p>而“清哪些段”则更依赖经验。经典 LFS 论文里的一条思路是区分<strong>热段</strong>和<strong>冷段</strong>：</p><ul><li>热段里的内容经常被覆盖，晚点清理更划算，因为过一阵可能会死掉更多块</li><li>冷段里的内容稳定，若其中混入少量垃圾，早点清理更容易回收出整段空间</li></ul><p>这里没有绝对完美的策略，但冷热分离提供了一个相当实用的方向</p><h4 id="崩溃恢复" tabindex="-1">崩溃恢复 <a class="header-anchor" href="#崩溃恢复" aria-label="Permalink to &quot;崩溃恢复&quot;">​</a></h4><p>LFS 同样要处理崩溃一致性问题，只是方式和 journaling 不同，关键在于 <code>CR</code> 必须可靠更新。为此，LFS 通常维护两个 <code>CR</code>，放在磁盘固定位置并交替写入。更新时采用比较谨慎的协议：</p><ul><li>先写头部，带时间戳</li><li>再写主体</li><li>最后写尾部，也带时间戳</li></ul><p>如果系统在更新 <code>CR</code> 中途崩溃，重启后只要比较头尾时间戳是否一致，就能判断哪个 <code>CR</code> 是最后一个完整版本</p><p>但 <code>CR</code> 并不会每次写都同步更新，它可能每隔几十秒才落盘一次。这意味着只靠 <code>CR</code> 恢复，可能会丢掉最近几十秒的更新</p><p>因此 LFS 还会做一件事，叫<strong>前滚 <code>roll forward</code></strong>：</p><ul><li>从最后一个一致的 <code>CR</code> 出发</li><li>沿着日志尾部继续扫描后续段</li><li>如果发现其中包含有效的新更新，就把这些更新重新并入当前文件系统状态</li></ul><p>可以把它理解为：<code>CR</code> 提供一个可靠但稍旧的恢复基点，roll-forward 尽量把基点之后已经落盘但还没进检查点的更新也捞回来</p><h3 id="数据完整性与保护" tabindex="-1">数据完整性与保护 <a class="header-anchor" href="#数据完整性与保护" aria-label="Permalink to &quot;数据完整性与保护&quot;">​</a></h3><p>现在我们来关注如何确保系统写进去的数据，和以后读出来的数据，真的是同一份内容？</p><h4 id="现代磁盘的故障模型已经变了" tabindex="-1">现代磁盘的故障模型已经变了 <a class="header-anchor" href="#现代磁盘的故障模型已经变了" aria-label="Permalink to &quot;现代磁盘的故障模型已经变了&quot;">​</a></h4><p>早期 RAID 设计里，大家经常假设磁盘符合 <strong>fail-stop</strong> 模型：</p><ul><li>要么磁盘正常工作</li><li>要么整个磁盘彻底挂掉</li></ul><p>这个模型很干净，也很适合做冗余恢复。但现代磁盘更麻烦，它们很多时候表现为 <strong>fail-partial</strong>：</p><ul><li>磁盘大体上还活着</li><li>但某些块会变得不可读</li><li>或者更糟，磁盘会返回“看起来正常、其实是错的”数据</li></ul><p>书里重点讨论了两类部分故障：</p><ul><li><strong>潜在扇区错误 <code>Latent-Sector Error, LSE</code></strong>：某些块已经坏了，读取时会明确报错</li><li><strong>块讹误 <code>block corruption</code></strong>：块内容错了，但设备自己可能没检测出来，属于<strong>无声故障 <code>silent fault</code></strong></li></ul><p>这两类问题都不算高频，但在大规模系统里已经足够常见。研究数据显示，在约 3 年、150 万块磁盘的观察中：</p><ul><li>廉价盘出现过 LSE 的比例大约是 <code>9.4%</code></li><li>高端盘出现过 LSE 的比例大约是 <code>1.4%</code></li><li>廉价盘出现过块讹误的比例大约是 <code>0.5%</code></li><li>高端盘出现过块讹误的比例大约是 <code>0.05%</code></li></ul><p>即便买更贵的盘，也只是把问题变少，而不是让问题消失</p><h4 id="先处理容易的-lse" tabindex="-1">先处理容易的：LSE <a class="header-anchor" href="#先处理容易的-lse" aria-label="Permalink to &quot;先处理容易的：LSE&quot;">​</a></h4><p>LSE 相对容易处理，因为它是<strong>可检测的</strong>。读取某个块时，磁盘会直接返回错误。这时存储系统只要利用已有的冗余副本恢复即可：</p><ul><li>在镜像里读另一份副本</li><li>在 RAID-4/5 里利用其他数据块和奇偶校验块重建</li></ul><p>所以 LSE 的关键不在“怎么发现”，而在“有没有足够的冗余帮你补回来”</p><p>这也是为什么后来的 RAID 设计会更在意重建期间再次出错的问题。比如 RAID-5 某块盘整盘失效后，系统需要读同一条带上的其他块来重建；如果这时其他盘上再碰到一个 LSE，重建就可能失败。于是一些系统会采用双校验之类的设计来提高容错上限</p><h4 id="更麻烦的是无声讹误" tabindex="-1">更麻烦的是无声讹误 <a class="header-anchor" href="#更麻烦的是无声讹误" aria-label="Permalink to &quot;更麻烦的是无声讹误&quot;">​</a></h4><p>比 LSE 更危险的是块讹误，因为系统读到的数据“形式上正常”，却不一定是真的。这种问题可能来自：</p><ul><li>磁盘介质或固件异常</li><li>控制器把块写到了错误位置</li><li>总线传输出错</li><li>设备报告写入完成，但数据其实没真正落盘</li></ul><p>只靠“设备有没有报错”已经不够，系统必须自己想办法验证数据</p><h4 id="核心武器-校验和-checksum" tabindex="-1">核心武器：校验和 <code>checksum</code> <a class="header-anchor" href="#核心武器-校验和-checksum" aria-label="Permalink to &quot;核心武器：校验和 `checksum`&quot;">​</a></h4><p>现代存储系统最常见的做法是给每个块计算一个<strong>校验和</strong>。思路很简单：</p><ul><li>写入块 <code>D</code> 时，先算出它的校验和 <code>C(D)</code></li><li>把 <code>C(D)</code> 和块一起存起来</li><li>以后读取 <code>D</code> 时，再重新计算一遍当前数据的校验和</li><li>把“存储的校验和”和“现算的校验和”做比较</li></ul><p>如果两者一致，数据大概率没坏；如果不一致，就说明块在某个环节被改坏了</p><p>注意这里并不存在“完美校验和”。因为你总是在用很短的摘要去概括很大的数据块，所以不同数据最终得到相同摘要的**碰撞 <code>collision</code>**始终可能存在。设计目标不是彻底杜绝碰撞，而是在合理成本下把碰撞概率压得足够低</p><h4 id="常见校验和函数" tabindex="-1">常见校验和函数 <a class="header-anchor" href="#常见校验和函数" aria-label="Permalink to &quot;常见校验和函数&quot;">​</a></h4><p>不同校验和的主要权衡在于两点：</p><ul><li><strong>强度</strong>：多大程度上能发现错误</li><li><strong>速度</strong>：计算它要花多少 CPU</li></ul><p>常见方案大致有这几类：</p><ul><li><strong>XOR 校验和</strong>：实现简单、速度快，但对某些成对位翻转不敏感</li><li><strong>加法校验和</strong>：也很快，能发现很多变化，但对某些重排或位移不够强</li><li><strong>Fletcher checksum</strong>：比前两者更强，能检测单比特、双比特和大部分突发错误</li><li><strong>CRC</strong>：工程里很常见，本质是把整块数据当作一个大二进制数去做模运算，检测能力很强，也有成熟高效实现</li></ul><p>这里没有免费的午餐。保护越强，通常计算成本越高</p><h4 id="校验和放在哪里" tabindex="-1">校验和放在哪里 <a class="header-anchor" href="#校验和放在哪里" aria-label="Permalink to &quot;校验和放在哪里&quot;">​</a></h4><p>有了校验和之后，下一个问题是布局：<strong>校验和怎么和数据一起存？</strong></p><p>最理想的方式是“每个块都带着自己的校验和”。如果硬件支持额外元数据区域，例如每个扇区除了数据还有几个字节可以存校验和</p><p>但如果磁盘只提供普通扇区，文件系统就得自己安排布局。一种常见办法是：</p><ul><li>先放一组校验和块</li><li>再放对应的一组数据块</li></ul><p>这种布局能工作，但更新代价更高。比如只改一个数据块时，系统还得顺带读取并更新它所在的校验和块，于是会多出额外 I/O</p><h4 id="读取时怎么使用校验和" tabindex="-1">读取时怎么使用校验和 <a class="header-anchor" href="#读取时怎么使用校验和" aria-label="Permalink to &quot;读取时怎么使用校验和&quot;">​</a></h4><p>读取块 <code>D</code> 时，可以把两份值区分成：</p><ul><li><strong>存储的校验和</strong> <code>Cs(D)</code></li><li><strong>计算得到的校验和</strong> <code>Cc(D)</code></li></ul><p>流程就是：</p><ol><li>读出块 <code>D</code></li><li>读出与之对应的 <code>Cs(D)</code></li><li>对当前读出的 <code>D</code> 重新计算 <code>Cc(D)</code></li><li>比较 <code>Cs(D)</code> 和 <code>Cc(D)</code></li></ol><p>如果：</p><ul><li><code>Cs(D) == Cc(D)</code>：数据大概率可信</li><li><code>Cs(D) != Cc(D)</code>：数据出现讹误</li></ul><p>一旦检测到讹误，恢复方式和 LSE 类似：</p><ul><li>有冗余副本就尝试修复</li><li>没有冗余就只能报错</li></ul><p>所以校验和解决的是<strong>检测</strong>问题，不会自动凭空创造出正确数据</p><h4 id="新问题-1-错误位置写入-misdirected-write" tabindex="-1">新问题 1：错误位置写入 <code>misdirected write</code> <a class="header-anchor" href="#新问题-1-错误位置写入-misdirected-write" aria-label="Permalink to &quot;新问题 1：错误位置写入 `misdirected write`&quot;">​</a></h4><p>基本校验和方案可以发现“块内容被改坏”，但它还挡不住一种特殊错误：<strong>数据被完整地写到了错误的位置。</strong></p><p>例如，本来应该把块 <code>D_x</code> 写到地址 <code>x</code>，结果设备写到了地址 <code>y</code>。这时如果你只检查块内容本身：</p><ul><li>数据内容看起来没坏</li><li>校验和也可能完全匹配</li></ul><p>但它就是出现在不该出现的位置</p><p>解决办法是：<strong>让校验和覆盖的不只是数据内容，还包括物理身份。</strong> 比如把这些信息一起写下来：</p><ul><li>校验和</li><li>磁盘号</li><li>块号或扇区偏移</li></ul><p>这样，系统在读某个位置时，不只验证“数据内容对不对”，还验证“这份数据是不是本来就属于这里”。如果物理 ID 对不上，就能检测出 misdirected write</p><h4 id="新问题-2-丢失写入-lost-write" tabindex="-1">新问题 2：丢失写入 <code>lost write</code> <a class="header-anchor" href="#新问题-2-丢失写入-lost-write" aria-label="Permalink to &quot;新问题 2：丢失写入 `lost write`&quot;">​</a></h4><p>还有一种更刁钻的故障叫 <strong>lost write</strong>：</p><ul><li>上层收到了“写入完成”的通知</li><li>但数据实际上根本没真正持久化</li><li>磁盘里留下的仍然是旧块内容</li></ul><p>这时，前面那些方案为什么不够？因为：</p><ul><li>旧数据有旧校验和</li><li>旧数据所在的物理位置也是对的</li></ul><p>也就是说，<strong>“内容 + 位置”同时验证都可能通过</strong>，但块其实没有更新成功。一种办法是 <strong>write verify / read-after-write</strong> 每次写完立刻再读回来验证。有效，但代价非常高，等于显著增加写入 I/O</p><p>更聪明的办法是在系统的其他层也保存校验和。书里举的例子是 ZFS：它会把子块的校验和存到上层元数据里，比如 inode 或间接块中。这样即使数据块本身还是旧内容，只要上层元数据已经更新，校验和就会对不上，于是可以发现 lost write</p><h4 id="磁盘擦净-scrubbing" tabindex="-1">磁盘擦净 <code>scrubbing</code> <a class="header-anchor" href="#磁盘擦净-scrubbing" aria-label="Permalink to &quot;磁盘擦净 `scrubbing`&quot;">​</a></h4><p>如果校验和只在“用户正好读取这个块”时才检查，那很多冷数据可能几年都不会被验证一次。这显然不够安全。所以可靠存储系统通常会定期做 <strong>scrub</strong>：</p><ul><li>顺序扫描整个磁盘或整个阵列</li><li>逐块读取</li><li>重新计算校验和</li><li>一旦发现某个副本损坏，就趁其他副本还好时修复它</li></ul><p>scrub 的价值在于：<strong>主动发现那些平时不会被访问的数据问题，避免等到所有副本都坏了才第一次暴露</strong></p><p>这也是为什么很多系统会把 scrub 安排成每天、每周，或者在空闲时间定期跑一次</p><h4 id="校验和的开销" tabindex="-1">校验和的开销 <a class="header-anchor" href="#校验和的开销" aria-label="Permalink to &quot;校验和的开销&quot;">​</a></h4><p>校验和当然不是零成本，主要有两类开销</p><p>第一类是<strong>空间开销</strong>：</p><ul><li>磁盘上要额外存校验和</li><li>某些场景下内存里也要临时或长期保留校验和</li></ul><p>如果是每 <code>4KB</code> 数据配 <code>8B</code> 校验和，磁盘空间开销大约只有 <code>0.19%</code>，通常不算大</p><p>第二类是<strong>时间开销</strong>：</p><ul><li>写入时要计算校验和</li><li>读取时要重新计算并比对</li><li>如果校验和和数据分开存，还会带来额外 I/O</li><li>scrub 本身也会消耗后台带宽</li></ul><p>因此，实际系统通常会做很多工程优化，比如把“数据拷贝”和“校验和计算”合并在一条流水线上执行，尽量摊薄 CPU 成本</p>',226)])])}const g=i(s,[["render",n]]);export{u as __pageData,g as default};
